// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract MockSurpSwapV3TwapPool {
    address public immutable token0;
    address public immutable token1;
    int24 public tick;

    constructor(address token0_, address token1_) {
        token0 = token0_;
        token1 = token1_;
    }

    function setTick(int24 tick_) external {
        tick = tick_;
    }

    function observe(uint32[] calldata secondsAgos)
        external
        view
        returns (int56[] memory tickCumulatives, uint160[] memory secondsPerLiquidityCumulativeX128s)
    {
        tickCumulatives = new int56[](secondsAgos.length);
        secondsPerLiquidityCumulativeX128s = new uint160[](secondsAgos.length);
        for (uint256 i = 0; i < secondsAgos.length; i++) {
            tickCumulatives[i] = int56(tick) * int56(uint56(secondsAgos[0] - secondsAgos[i]));
        }
    }
}

contracts/P2EManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

contract P2EManager is Ownable {
    using SafeERC20 for IERC20;

    IERC20 public token;
    mapping(address => bool) public isMiningPool;
    address public payPalRelayer;
    uint256 public maxPayPalPayoutPerTransaction;
    uint256 public dailyPayPalPayoutLimit;
    uint256 public dailyPayPalPayoutDay;
    uint256 public dailyPayPalPayoutUsed;
    mapping(bytes32 => bool) public processedPayPalPayments;

    event PayoutExecuted(address indexed user, uint256 amount);
    event EmergencyWithdrawn(address indexed owner, address indexed to, uint256 amount);
    event MiningPoolStatusUpdated(address indexed pool, bool status);
    event PayPalPayoutConfigUpdated(
        address indexed relayer,
        uint256 maxPerTransaction,
        uint256 dailyLimit
    );
    event PayPalPayoutReleased(
        bytes32 indexed paymentId,
        address indexed to,
        uint256 amount,
        uint256 day
    );

    constructor(address _token) {
        token = IERC20(_token);
    }

    function setMiningPoolStatus(address _pool, bool _status) external onlyOwner {
        isMiningPool[_pool] = _status;
        emit MiningPoolStatusUpdated(_pool, _status);
    }

    function setPayPalPayoutConfig(
        address relayer,
        uint256 maxPerTransaction,
        uint256 dailyLimit
    ) external onlyOwner {
        bool disabled = relayer == address(0) &&
            maxPerTransaction == 0 &&
            dailyLimit == 0;
        require(
            disabled ||
                (relayer != address(0) &&
                    maxPerTransaction > 0 &&
                    dailyLimit >= maxPerTransaction),
            "invalid payout config"
        );

        payPalRelayer = relayer;
        maxPayPalPayoutPerTransaction = maxPerTransaction;
        dailyPayPalPayoutLimit = dailyLimit;
        emit PayPalPayoutConfigUpdated(relayer, maxPerTransaction, dailyLimit);
    }

    function fund(uint256 amount) external onlyOwner {
        token.safeTransferFrom(msg.sender, address(this), amount);
    }

    function payout(address user, uint256 amount) external {
        require(isMiningPool[msg.sender], "Bukan pool resmi");
        require(token.balanceOf(address(this)) >= amount, "Dana vault P2E habis");

        token.safeTransfer(user, amount);
        emit PayoutExecuted(user, amount);
    }

    function releaseForPayPal(bytes32 paymentId, address to, uint256 amount) external {
        require(msg.sender == payPalRelayer && payPalRelayer != address(0), "not PayPal relayer");
        require(paymentId != bytes32(0), "zero payment id");
        require(!processedPayPalPayments[paymentId], "payment already processed");
        require(to != address(0), "zero address");
        require(amount > 0, "zero amount");
        require(amount <= maxPayPalPayoutPerTransaction, "exceeds transaction limit");

        uint256 currentDay = block.timestamp / 1 days;
        if (dailyPayPalPayoutDay != currentDay) {
            dailyPayPalPayoutDay = currentDay;
            dailyPayPalPayoutUsed = 0;
        }
        require(
            dailyPayPalPayoutUsed + amount <= dailyPayPalPayoutLimit,
            "exceeds daily limit"
        );
        require(token.balanceOf(address(this)) >= amount, "Dana vault P2E habis");

        dailyPayPalPayoutUsed += amount;
        processedPayPalPayments[paymentId] = true;
        token.safeTransfer(to, amount);
        emit PayPalPayoutReleased(paymentId, to, amount, currentDay);
    }

    function emergencyWithdraw(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "Invalid address");
        require(token.balanceOf(address(this)) >= amount, "Exceeds balance");

        token.safeTransfer(to, amount);
        emit EmergencyWithdrawn(msg.sender, to, amount);
    }
}

contracts/PolygonDexSwapHelper.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IPolygonWpol is IERC20 {
    function deposit() external payable;
    function withdraw(uint256 amount) external;
}

interface IUniswapV3SwapRouter {
    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    function exactInputSingle(ExactInputSingleParams calldata params)
        external
        payable
        returns (uint256 amountOut);
}

interface IQuickSwapAlgebraSwapRouter {
    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 limitSqrtPrice;
    }

    function exactInputSingle(ExactInputSingleParams calldata params)
        external
        payable
        returns (uint256 amountOut);
}

contract PolygonDexSwapHelper is ReentrancyGuard {
    using SafeERC20 for IERC20;

    address public constant WPOL = 0x0d500B1d8E8eF31E21C99d1Db9A6444d3ADf1270;
    address public constant UNISWAP_V3_ROUTER = 0xE592427A0AEce92De3Edee1F18E0157C05861564;
    address public constant QUICKSWAP_V3_ROUTER = 0xf5b509bB0909a69B1c207E495f687a596C168E12;
    uint256 private constant MAX_DEADLINE_WINDOW = 30 minutes;

    enum Dex {
        UNISWAP_V3,
        QUICKSWAP_V3
    }

    event SwapExecuted(
        address indexed user,
        Dex indexed dex,
        address indexed tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOut
    );

    constructor() {
        require(block.chainid == 137, "Polygon mainnet only");
        require(UNISWAP_V3_ROUTER.code.length > 0, "Uniswap router missing");
        require(QUICKSWAP_V3_ROUTER.code.length > 0, "QuickSwap router missing");
        require(WPOL.code.length > 0, "WPOL missing");
    }

    function buyWithPOL(
        address tokenOut,
        Dex dex,
        uint24 uniswapFee,
        uint256 amountOutMinimum,
        uint256 deadline
    ) external payable nonReentrant returns (uint256 amountOut) {
        _validateSwap(tokenOut, WPOL, amountOutMinimum, deadline);
        require(msg.value > 0, "zero POL input");
        require(tokenOut != WPOL, "token is WPOL");

        IPolygonWpol(WPOL).deposit{value: msg.value}();
        IERC20(WPOL).forceApprove(_routerFor(dex), msg.value);

        amountOut = _swapExactInput(
            dex,
            WPOL,
            tokenOut,
            msg.value,
            amountOutMinimum,
            deadline,
            uniswapFee,
            msg.sender
        );

        IERC20(WPOL).forceApprove(_routerFor(dex), 0);
        emit SwapExecuted(msg.sender, dex, WPOL, tokenOut, msg.value, amountOut);
    }

    function sellForPOL(
        address tokenIn,
        Dex dex,
        uint24 uniswapFee,
        uint256 amountIn,
        uint256 amountOutMinimum,
        uint256 deadline
    ) external nonReentrant returns (uint256 amountOut) {
        _validateSwap(WPOL, tokenIn, amountOutMinimum, deadline);
        require(tokenIn != WPOL, "token is WPOL");
        require(amountIn > 0, "zero token input");

        IERC20(tokenIn).safeTransferFrom(msg.sender, address(this), amountIn);
        IERC20(tokenIn).forceApprove(_routerFor(dex), amountIn);

        amountOut = _swapExactInput(
            dex,
            tokenIn,
            WPOL,
            amountIn,
            amountOutMinimum,
            deadline,
            uniswapFee,
            address(this)
        );

        IERC20(tokenIn).forceApprove(_routerFor(dex), 0);
        IPolygonWpol(WPOL).withdraw(amountOut);
        (bool sent, ) = payable(msg.sender).call{value: amountOut}("");
        require(sent, "POL transfer failed");

        emit SwapExecuted(msg.sender, dex, tokenIn, WPOL, amountIn, amountOut);
    }

    function swapTokens(
        address tokenIn,
        address tokenOut,
        Dex dex,
        uint24 uniswapFee,
        uint256 amountIn,
        uint256 amountOutMinimum,
        uint256 deadline
    ) external nonReentrant returns (uint256 amountOut) {
        _validateSwap(tokenOut, tokenIn, amountOutMinimum, deadline);
        require(tokenIn != tokenOut, "identical tokens");
        require(amountIn > 0, "zero token input");

        IERC20(tokenIn).safeTransferFrom(msg.sender, address(this), amountIn);
        IERC20(tokenIn).forceApprove(_routerFor(dex), amountIn);

        amountOut = _swapExactInput(
            dex,
            tokenIn,
            tokenOut,
            amountIn,
            amountOutMinimum,
            deadline,
            uniswapFee,
            msg.sender
        );

        IERC20(tokenIn).forceApprove(_routerFor(dex), 0);
        emit SwapExecuted(msg.sender, dex, tokenIn, tokenOut, amountIn, amountOut);
    }

    function _swapExactInput(
        Dex dex,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOutMinimum,
        uint256 deadline,
        uint24 uniswapFee,
        address recipient
    ) private returns (uint256 amountOut) {
        if (dex == Dex.UNISWAP_V3) {
            require(
                uniswapFee == 100 ||
                    uniswapFee == 500 ||
                    uniswapFee == 3000 ||
                    uniswapFee == 10000,
                "invalid fee"
            );
            return IUniswapV3SwapRouter(UNISWAP_V3_ROUTER).exactInputSingle(
                IUniswapV3SwapRouter.ExactInputSingleParams({
                    tokenIn: tokenIn,
                    tokenOut: tokenOut,
                    fee: uniswapFee,
                    recipient: recipient,
                    deadline: deadline,
                    amountIn: amountIn,
                    amountOutMinimum: amountOutMinimum,
                    sqrtPriceLimitX96: 0
                })
            );
        }

        require(dex == Dex.QUICKSWAP_V3, "unsupported DEX");
        require(uniswapFee == 0, "QuickSwap does not use a fee tier");
        return IQuickSwapAlgebraSwapRouter(QUICKSWAP_V3_ROUTER).exactInputSingle(
            IQuickSwapAlgebraSwapRouter.ExactInputSingleParams({
                tokenIn: tokenIn,
                tokenOut: tokenOut,
                recipient: recipient,
                deadline: deadline,
                amountIn: amountIn,
                amountOutMinimum: amountOutMinimum,
                limitSqrtPrice: 0
            })
        );
    }

    function _routerFor(Dex dex) private pure returns (address) {
        if (dex == Dex.UNISWAP_V3) {
            return UNISWAP_V3_ROUTER;
        }
        require(dex == Dex.QUICKSWAP_V3, "unsupported DEX");
        return QUICKSWAP_V3_ROUTER;
    }

    function _validateSwap(
        address tokenOut,
        address tokenIn,
        uint256 amountOutMinimum,
        uint256 deadline
    ) private view {
        require(tokenOut != address(0) && tokenIn != address(0), "zero token");
        require(amountOutMinimum > 0, "zero minimum output");
        require(deadline >= block.timestamp, "deadline expired");
        require(deadline <= block.timestamp + MAX_DEADLINE_WINDOW, "deadline too far");
    }

    receive() external payable {
        require(msg.sender == WPOL, "only WPOL may send POL");
    }
}

contracts/PolygonDualDexLiquidityHelper..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IUniswapV3PositionManager {
    struct MintParams {
        address token0;
        address token1;
        uint24 fee;
        int24 tickLower;
        int24 tickUpper;
        uint256 amount0Desired;
        uint256 amount1Desired;
        uint256 amount0Min;
        uint256 amount1Min;
        address recipient;
        uint256 deadline;
    }

    function mint(MintParams calldata params)
        external
        payable
        returns (uint256 tokenId, uint128 liquidity, uint256 amount0, uint256 amount1);
}

interface IQuickSwapV3PositionManager {
    struct MintParams {
        address token0;
        address token1;
        int24 tickLower;
        int24 tickUpper;
        uint256 amount0Desired;
        uint256 amount1Desired;
        uint256 amount0Min;
        uint256 amount1Min;
        address recipient;
        uint256 deadline;
    }

    function mint(MintParams calldata params)
        external
        payable
        returns (uint256 tokenId, uint128 liquidity, uint256 amount0, uint256 amount1);
}

contract PolygonDualDexLiquidityHelper is ReentrancyGuard {
    using SafeERC20 for IERC20;

    address public constant UNISWAP_V3_POSITION_MANAGER =
        0xC36442b4a4522E871399CD717aBDD847Ab11FE88;
    address public constant QUICKSWAP_V3_POSITION_MANAGER =
        0x8eF88E4c7CfbbaC1C163f7eddd4B578792201de6;

    event LiquidityAdded(
        address indexed provider,
        address indexed positionManager,
        uint256 indexed tokenId,
        uint128 liquidity,
        uint256 amount0,
        uint256 amount1
    );

    constructor() {
        require(block.chainid == 137, "Polygon mainnet only");
        require(UNISWAP_V3_POSITION_MANAGER.code.length > 0, "Uniswap manager missing");
        require(QUICKSWAP_V3_POSITION_MANAGER.code.length > 0, "QuickSwap manager missing");
    }

    function addUniswapV3Liquidity(
        IUniswapV3PositionManager.MintParams calldata params
    ) external nonReentrant returns (uint256 tokenId, uint128 liquidity, uint256 amount0, uint256 amount1) {
        _validate(
            params.token0,
            params.token1,
            params.tickLower,
            params.tickUpper,
            params.amount0Desired,
            params.amount1Desired,
            params.amount0Min,
            params.amount1Min,
            params.deadline
        );
        require(params.recipient == msg.sender, "Recipient must be caller");
        require(
            params.fee == 100 || params.fee == 500 || params.fee == 3000 || params.fee == 10000,
            "Invalid Uniswap fee"
        );

        _pullAndApprove(
            params.token0,
            params.token1,
            params.amount0Desired,
            params.amount1Desired,
            UNISWAP_V3_POSITION_MANAGER
        );
        (tokenId, liquidity, amount0, amount1) = IUniswapV3PositionManager(
            UNISWAP_V3_POSITION_MANAGER
        ).mint(
            IUniswapV3PositionManager.MintParams({
                token0: params.token0,
                token1: params.token1,
                fee: params.fee,
                tickLower: params.tickLower,
                tickUpper: params.tickUpper,
                amount0Desired: params.amount0Desired,
                amount1Desired: params.amount1Desired,
                amount0Min: params.amount0Min,
                amount1Min: params.amount1Min,
                recipient: msg.sender,
                deadline: params.deadline
            })
        );
        _refundAndClear(
            params.token0,
            params.token1,
            params.amount0Desired - amount0,
            params.amount1Desired - amount1,
            UNISWAP_V3_POSITION_MANAGER
        );
        emit LiquidityAdded(msg.sender, UNISWAP_V3_POSITION_MANAGER, tokenId, liquidity, amount0, amount1);
    }

    function addQuickSwapV3Liquidity(
        IQuickSwapV3PositionManager.MintParams calldata params
    ) external nonReentrant returns (uint256 tokenId, uint128 liquidity, uint256 amount0, uint256 amount1) {
        _validate(
            params.token0,
            params.token1,
            params.tickLower,
            params.tickUpper,
            params.amount0Desired,
            params.amount1Desired,
            params.amount0Min,
            params.amount1Min,
            params.deadline
        );
        require(params.recipient == msg.sender, "Recipient must be caller");

        _pullAndApprove(
            params.token0,
            params.token1,
            params.amount0Desired,
            params.amount1Desired,
            QUICKSWAP_V3_POSITION_MANAGER
        );
        (tokenId, liquidity, amount0, amount1) = IQuickSwapV3PositionManager(
            QUICKSWAP_V3_POSITION_MANAGER
        ).mint(
            IQuickSwapV3PositionManager.MintParams({
                token0: params.token0,
                token1: params.token1,
                tickLower: params.tickLower,
                tickUpper: params.tickUpper,
                amount0Desired: params.amount0Desired,
                amount1Desired: params.amount1Desired,
                amount0Min: params.amount0Min,
                amount1Min: params.amount1Min,
                recipient: msg.sender,
                deadline: params.deadline
            })
        );
        _refundAndClear(
            params.token0,
            params.token1,
            params.amount0Desired - amount0,
            params.amount1Desired - amount1,
            QUICKSWAP_V3_POSITION_MANAGER
        );
        emit LiquidityAdded(msg.sender, QUICKSWAP_V3_POSITION_MANAGER, tokenId, liquidity, amount0, amount1);
    }

    function _validate(
        address token0,
        address token1,
        int24 tickLower,
        int24 tickUpper,
        uint256 amount0Desired,
        uint256 amount1Desired,
        uint256 amount0Min,
        uint256 amount1Min,
        uint256 deadline
    ) private view {
        require(token0 != address(0) && token1 != address(0), "Zero token");
        require(uint160(token0) < uint160(token1), "Tokens not sorted");
        require(token0.code.length > 0 && token1.code.length > 0, "Token contract missing");
        require(tickLower < tickUpper, "Invalid tick range");
        require(amount0Desired > 0 && amount1Desired > 0, "Zero desired amount");
        require(amount0Min <= amount0Desired && amount1Min <= amount1Desired, "Minimum exceeds desired");
        require(deadline >= block.timestamp, "Deadline expired");
    }

    function _pullAndApprove(
        address token0,
        address token1,
        uint256 amount0,
        uint256 amount1,
        address positionManager
    ) private {
        IERC20(token0).safeTransferFrom(msg.sender, address(this), amount0);
        IERC20(token1).safeTransferFrom(msg.sender, address(this), amount1);
        IERC20(token0).safeApprove(positionManager, 0);
        IERC20(token1).safeApprove(positionManager, 0);
        IERC20(token0).safeApprove(positionManager, amount0);
        IERC20(token1).safeApprove(positionManager, amount1);
    }

    function _refundAndClear(
        address token0,
        address token1,
        uint256 refund0,
        uint256 refund1,
        address positionManager
    ) private {
        IERC20(token0).safeApprove(positionManager, 0);
        IERC20(token1).safeApprove(positionManager, 0);
        if (refund0 > 0) IERC20(token0).safeTransfer(msg.sender, refund0);
        if (refund1 > 0) IERC20(token1).safeTransfer(msg.sender, refund1);
    }
}

contracts/PublicStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "./libraries/SurpSwapV3Twap.sol";

interface IP2ERewardManager {
    function payout(address user, uint256 amount) external;
}

contract PublicStaking is Ownable, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 public constant BASE_APR_BPS = 20_000;
    uint256 public constant BPS_DENOMINATOR = 10_000;
    uint256 public constant SECONDS_PER_YEAR = 365 days;
    uint256 public constant LOCK_DURATION = 90 days;
    uint32 public constant MAX_APR_BPS = 100_000;

    IERC20 public immutable token;
    IP2ERewardManager public immutable p2eManager;
    address public immutable pricePool;
    address public immutable quoteToken;
    uint32 public immutable twapInterval;

    uint256 public committedRewards;
    uint256 public referencePriceX18;
    uint256 public referenceStakerCount;
    uint32 public minAprBps;
    uint32 public maxAprBps;
    uint32 public currentAprBps;
    uint256 public activeStakerCount;
    uint256 public cumulativeAprSeconds;
    uint64 public lastRateUpdateAt;
    bool public aprConfigured;

    struct Stake {
        uint256 amount;
        uint256 reservedReward;
        uint64 stakedAt;
        bool principalWithdrawn;
        bool rewardClaimed;
    }

    struct AprCheckpoint {
        uint64 timestamp;
        uint32 aprBps;
        uint256 cumulativeAprSeconds;
    }

    mapping(address => Stake) public stakes;
    AprCheckpoint[] private aprCheckpoints;

    event AprParametersUpdated(
        uint256 referencePriceX18,
        uint256 referenceStakerCount,
        uint32 minAprBps,
        uint32 maxAprBps
    );
    event AprCheckpointed(uint32 aprBps, uint256 priceX18, uint256 activeWallets);
    event Staked(address indexed account, uint256 amount, uint256 reservedReward, uint64 unlockAt);
    event PrincipalWithdrawn(address indexed account, uint256 amount);
    event RewardClaimed(address indexed account, uint256 amount);

    constructor(
        address token_,
        address p2eManager_,
        address pricePool_,
        address quoteToken_,
        uint32 twapInterval_,
        address admin_
    ) {
        require(token_ != address(0) && token_.code.length > 0, "Invalid token");
        require(p2eManager_ != address(0) && p2eManager_.code.length > 0, "Invalid P2E manager");
        require(pricePool_ != address(0) && pricePool_.code.length > 0, "Invalid price pool");
        require(quoteToken_ != address(0) && quoteToken_.code.length > 0, "Invalid quote token");
        require(token_ != quoteToken_, "Price tokens must differ");
        require(twapInterval_ > 0, "TWAP interval zero");
        require(admin_ != address(0), "Invalid admin");
        require(IERC20Metadata(token_).decimals() == 18, "Stake token must use 18 decimals");
        require(IERC20Metadata(quoteToken_).decimals() == 18, "Quote token must use 18 decimals");

        token = IERC20(token_);
        p2eManager = IP2ERewardManager(p2eManager_);
        pricePool = pricePool_;
        quoteToken = quoteToken_;
        twapInterval = twapInterval_;
        lastRateUpdateAt = uint64(block.timestamp);
        aprCheckpoints.push(
            AprCheckpoint({
                timestamp: uint64(block.timestamp),
                aprBps: 0,
                cumulativeAprSeconds: 0
            })
        );
        _transferOwnership(admin_);
    }

    function setAprParameters(
        uint256 referencePriceX18_,
        uint256 referenceStakerCount_,
        uint32 minAprBps_,
        uint32 maxAprBps_
    ) external onlyOwner {
        require(activeStakerCount == 0, "Cannot change parameters with active stakes");
        require(referencePriceX18_ > 0, "Reference price zero");
        require(referenceStakerCount_ > 0, "Reference wallet count zero");
        require(minAprBps_ <= maxAprBps_, "Invalid APR range");
        require(maxAprBps_ <= MAX_APR_BPS, "Maximum APR too high");
        require(
            SurpSwapV3Twap.priceX18(pricePool, address(token), quoteToken, twapInterval) > 0,
            "Invalid TWAP price"
        );

        _accrueCurrentRate();
        referencePriceX18 = referencePriceX18_;
        referenceStakerCount = referenceStakerCount_;
        minAprBps = minAprBps_;
        maxAprBps = maxAprBps_;
        aprConfigured = true;
        _setCurrentApr(_calculateApr());
        emit AprParametersUpdated(
            referencePriceX18_,
            referenceStakerCount_,
            minAprBps_,
            maxAprBps_
        );
    }

    function currentPriceX18() external view returns (uint256) {
        return SurpSwapV3Twap.priceX18(pricePool, address(token), quoteToken, twapInterval);
    }

    function checkpointApr() external whenNotPaused {
        require(aprConfigured, "APR parameters not configured");
        _accrueCurrentRate();
        _setCurrentApr(_calculateApr());
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function stake(uint256 amount) external nonReentrant whenNotPaused {
        require(aprConfigured, "APR parameters not configured");
        require(amount > 0, "Stake amount zero");
        Stake storage position = stakes[msg.sender];
        require(
            position.amount == 0 || (position.principalWithdrawn && position.rewardClaimed),
            "Existing stake not settled"
        );

        _accrueCurrentRate();
        uint256 reservedReward = Math.mulDiv(
            amount,
            uint256(maxAprBps) * LOCK_DURATION,
            BPS_DENOMINATOR * SECONDS_PER_YEAR
        );
        require(reservedReward > 0, "Stake too small for reward");
        require(
            committedRewards + reservedReward <= token.balanceOf(address(p2eManager)),
            "Insufficient P2E balance for reward commitments"
        );

        if (position.amount != 0) delete stakes[msg.sender];
        position.amount = amount;
        position.reservedReward = reservedReward;
        position.stakedAt = uint64(block.timestamp);
        committedRewards += reservedReward;
        token.safeTransferFrom(msg.sender, address(this), amount);
        activeStakerCount++;
        _setCurrentApr(_calculateApr());

        emit Staked(
            msg.sender,
            amount,
            reservedReward,
            uint64(block.timestamp + LOCK_DURATION)
        );
    }

    function earnedReward(address account) public view returns (uint256) {
        Stake storage position = stakes[account];
        if (position.amount == 0 || position.rewardClaimed) return 0;

        uint256 unlockAt = uint256(position.stakedAt) + LOCK_DURATION;
        uint256 endAt = block.timestamp < unlockAt ? block.timestamp : unlockAt;
        if (endAt <= position.stakedAt) return 0;
        uint256 accruedAprSeconds = _cumulativeAprAt(endAt) -
            _cumulativeAprAt(position.stakedAt);
        uint256 reward = Math.mulDiv(
            position.amount,
            accruedAprSeconds,
            BPS_DENOMINATOR * SECONDS_PER_YEAR
        );
        return reward < position.reservedReward ? reward : position.reservedReward;
    }

    function withdrawPrincipal() external nonReentrant {
        Stake storage position = stakes[msg.sender];
        require(position.amount > 0, "No active stake");
        require(block.timestamp >= uint256(position.stakedAt) + LOCK_DURATION, "Stake is locked");
        require(!position.principalWithdrawn, "Principal already withdrawn");

        _accrueCurrentRate();
        position.principalWithdrawn = true;
        uint256 amount = position.amount;
        token.safeTransfer(msg.sender, amount);
        activeStakerCount--;
        _setCurrentApr(_calculateApr());
        _clearSettledStake(msg.sender, position);
        emit PrincipalWithdrawn(msg.sender, amount);
    }

    function claimReward() external nonReentrant {
        Stake storage position = stakes[msg.sender];
        require(position.amount > 0, "No active stake");
        require(block.timestamp >= uint256(position.stakedAt) + LOCK_DURATION, "Stake is locked");
        require(!position.rewardClaimed, "Reward already claimed");

        _accrueCurrentRate();
        uint256 reward = earnedReward(msg.sender);
        position.rewardClaimed = true;
        committedRewards -= position.reservedReward;
        p2eManager.payout(msg.sender, reward);
        _clearSettledStake(msg.sender, position);
        emit RewardClaimed(msg.sender, reward);
    }

    function aprCheckpointCount() external view returns (uint256) {
        return aprCheckpoints.length;
    }

    function availableRewardBalance() external view returns (uint256) {
        uint256 p2eBalance = token.balanceOf(address(p2eManager));
        return p2eBalance > committedRewards ? p2eBalance - committedRewards : 0;
    }

    function _calculateApr() private view returns (uint32) {
        if (activeStakerCount == 0) return 0;
        uint256 priceX18 = SurpSwapV3Twap.priceX18(
            pricePool,
            address(token),
            quoteToken,
            twapInterval
        );
        uint256 apr = Math.mulDiv(BASE_APR_BPS, priceX18, referencePriceX18);
        apr = Math.mulDiv(apr, referenceStakerCount, activeStakerCount);
        if (apr < minAprBps) apr = minAprBps;
        if (apr > maxAprBps) apr = maxAprBps;
        return uint32(apr);
    }

    function _accrueCurrentRate() private {
        uint64 now_ = uint64(block.timestamp);
        uint256 elapsed = now_ - lastRateUpdateAt;
        if (elapsed > 0) {
            cumulativeAprSeconds += uint256(currentAprBps) * elapsed;
            lastRateUpdateAt = now_;
        }
        _storeAprCheckpoint(now_);
    }

    function _setCurrentApr(uint32 newAprBps) private {
        currentAprBps = newAprBps;
        lastRateUpdateAt = uint64(block.timestamp);
        _storeAprCheckpoint(uint64(block.timestamp));
        uint256 priceX18 = activeStakerCount == 0
            ? 0
            : SurpSwapV3Twap.priceX18(pricePool, address(token), quoteToken, twapInterval);
        emit AprCheckpointed(newAprBps, priceX18, activeStakerCount);
    }

    function _storeAprCheckpoint(uint64 timestamp) private {
        uint256 length = aprCheckpoints.length;
        AprCheckpoint memory checkpoint = AprCheckpoint({
            timestamp: timestamp,
            aprBps: currentAprBps,
            cumulativeAprSeconds: cumulativeAprSeconds
        });
        if (aprCheckpoints[length - 1].timestamp == timestamp) {
            aprCheckpoints[length - 1] = checkpoint;
        } else {
            aprCheckpoints.push(checkpoint);
        }
    }

    function _cumulativeAprAt(uint256 timestamp) private view returns (uint256) {
        uint256 low;
        uint256 high = aprCheckpoints.length;
        while (low < high) {
            uint256 mid = (low + high) / 2;
            if (aprCheckpoints[mid].timestamp <= timestamp) low = mid + 1;
            else high = mid;
        }
        require(low > 0, "APR checkpoint missing");

        AprCheckpoint storage checkpoint = aprCheckpoints[low - 1];
        return
            checkpoint.cumulativeAprSeconds +
            uint256(checkpoint.aprBps) * (timestamp - checkpoint.timestamp);
    }

    function _clearSettledStake(address account, Stake storage position) private {
        if (position.principalWithdrawn && position.rewardClaimed) delete stakes[account];
    }
}

