// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface INFTContract {
    // Menambahkan parameter uint256 xp di akhir fungsi
    function updateStatsFromShop(uint256 tokenId, uint8 stamina, uint8 durability, uint256 bank, uint256 xp) external;
    function ownerOf(uint256 tokenId) external view returns (address);
}

contract SRP_Shop is Ownable {
    using SafeERC20 for IERC20;

    IERC20 public token;

    uint256 public staminaPrice;
    uint256 public durabilityPrice;
    uint256 public bankPrice;
    address public salesTreasury;

    uint8 public staminaStep = 1;
    uint8 public durabilityStep = 1;
    uint256 public bankStep = 10; // Nilai input 10 murni dari owner

    mapping(address => bool) public isWhitelistedNFT;

    event UpgradeBought(address indexed user, address indexed nftContract, uint256 indexed tokenId, string upgradeType, uint256 cost);
    event PricesUpdated(uint256 staminaPrice, uint256 durabilityPrice, uint256 bankPrice);
    event StepsUpdated(uint8 staminaStep, uint8 durabilityStep, uint256 bankStep);
    event SalesTreasuryUpdated(address indexed treasury);

    // KEMBALI KE GAYA KODE LU: Constructor kosongan mengikuti standar OpenZeppelin v4
    constructor(address _token) {
        require(_token != address(0) && _token.code.length > 0, "Invalid payment token");
        token = IERC20(_token);
    }

    function setNFTWhitelist(address _nftContract, bool _status) external onlyOwner {
        require(_nftContract != address(0), "Invalid NFT contract");
        if (_status) {
            require(_nftContract.code.length > 0, "NFT contract has no code");
        }
        isWhitelistedNFT[_nftContract] = _status;
    }

    function setPrices(uint256 _staminaPrice, uint256 _durabilityPrice, uint256 _bankPrice) external onlyOwner {
        staminaPrice = _staminaPrice;
        durabilityPrice = _durabilityPrice;
        bankPrice = _bankPrice;
        emit PricesUpdated(_staminaPrice, _durabilityPrice, _bankPrice);
    }

    function setSteps(uint8 _staminaStep, uint8 _durabilityStep, uint256 _bankStep) external onlyOwner {
        staminaStep = _staminaStep;
        durabilityStep = _durabilityStep;
        bankStep = _bankStep;
        emit StepsUpdated(_staminaStep, _durabilityStep, _bankStep);
    }

    function setSalesTreasury(address treasury) external onlyOwner {
        salesTreasury = treasury;
        emit SalesTreasuryUpdated(treasury);
    }

    // Tetap menjaga fitur volume kuantitas banyak sekaligus
    function buyStamina(address nftContract, uint256 tokenId, uint256 volume) external {
        require(volume > 0, "Kuantitas minimal 1");
        require(isWhitelistedNFT[nftContract], "NFT tidak terdaftar di shop");
        require(INFTContract(nftContract).ownerOf(tokenId) == msg.sender, "Bukan pemilik NFT");
        require(staminaPrice > 0, "Harga stamina belum diset");

        uint256 totalCost = staminaPrice * volume;
        uint256 requestedStep = uint256(staminaStep) * volume;
        uint8 totalStep = requestedStep > type(uint8).max
            ? type(uint8).max
            : uint8(requestedStep);

        token.safeTransferFrom(
            msg.sender,
            salesTreasury == address(0) ? address(this) : salesTreasury,
            totalCost
        );
        // Mengirimkan angka 1 untuk parameter XP
        INFTContract(nftContract).updateStatsFromShop(tokenId, totalStep, 0, 0, 1);

        emit UpgradeBought(msg.sender, nftContract, tokenId, "STAMINA", totalCost);
    }

    // Tetap menjaga fitur volume kuantitas banyak sekaligus
    function buyDurability(address nftContract, uint256 tokenId, uint256 volume) external {
        require(volume > 0, "Kuantitas minimal 1");
        require(isWhitelistedNFT[nftContract], "NFT tidak terdaftar di shop");
        require(INFTContract(nftContract).ownerOf(tokenId) == msg.sender, "Bukan pemilik NFT");
        require(durabilityPrice > 0, "Harga durability belum diset");

        uint256 totalCost = durabilityPrice * volume;
        uint256 requestedStep = uint256(durabilityStep) * volume;
        uint8 totalStep = requestedStep > type(uint8).max
            ? type(uint8).max
            : uint8(requestedStep);

        token.safeTransferFrom(
            msg.sender,
            salesTreasury == address(0) ? address(this) : salesTreasury,
            totalCost
        );
        // Mengirimkan angka 1 untuk parameter XP
        INFTContract(nftContract).updateStatsFromShop(tokenId, 0, totalStep, 0, 1);

        emit UpgradeBought(msg.sender, nftContract, tokenId, "DURABILITY", totalCost);
    }

    // Tetap menjaga fitur volume kuantitas banyak sekaligus
    function buyBank(address nftContract, uint256 tokenId, uint256 volume) external {
        require(volume > 0, "Kuantitas minimal 1");
        require(isWhitelistedNFT[nftContract], "NFT tidak terdaftar di shop");
        require(INFTContract(nftContract).ownerOf(tokenId) == msg.sender, "Bukan pemilik NFT");
        require(bankPrice > 0, "Harga bank belum diset");

        uint256 totalCost = bankPrice * volume;
        uint256 totalStep = (bankStep * 10**18) * volume;

        token.safeTransferFrom(
            msg.sender,
            salesTreasury == address(0) ? address(this) : salesTreasury,
            totalCost
        );
        // Mengirimkan angka 1 untuk parameter XP
        INFTContract(nftContract).updateStatsFromShop(tokenId, 0, 0, totalStep, 1);

        emit UpgradeBought(msg.sender, nftContract, tokenId, "BANK", totalCost);
    }

    function withdrawShopTokens(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "Invalid address");
        token.safeTransfer(to, amount);
    }
}

contracts/StandarRupiah.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

contract StandarRupiah is ERC20, Ownable2Step {
    using SafeERC20 for IERC20;

    uint256 public constant MAX_SUPPLY = 271_000_000_000_000 * 1e18;

    address public lpManager;
    address public p2eManager;

    bool public distributed;

    event VaultsSet(address lpManager, address p2eManager);
    event Distributed(uint256 lpAmount, uint256 p2eAmount);

    // Event tambahan buat tracking fitur rescue
    event EmergencyWithdrawNative(address indexed owner, uint256 amount);
    event EmergencyRescueToken(address indexed token, address indexed owner, uint256 amount);

    // Pastikan pakai Ownable(msg.sender) kalau lu pakai OpenZeppelin v5
    constructor() ERC20("StandardRupiah", "SRp") {}

    // ============================================================
    // SET VAULT (CUMA SEKALI)
    // ============================================================

    function setVaults(address _lpManager, address _p2eManager) external onlyOwner {
        require(!distributed, "locked");
        require(_lpManager != address(0) && _p2eManager != address(0), "zero");
        require(_lpManager != _p2eManager, "same");

        lpManager = _lpManager;
        p2eManager = _p2eManager;

        emit VaultsSet(_lpManager, _p2eManager);
    }

    // ============================================================
    // DISTRIBUTE SUPPLY
    // ============================================================

    function distribute() external onlyOwner {
        require(!distributed, "already");
        require(lpManager != address(0) && p2eManager != address(0), "vault missing");

        distributed = true;

        uint256 lpAmount = (MAX_SUPPLY * 60) / 100;
        uint256 p2eAmount = MAX_SUPPLY - lpAmount;

        _mint(lpManager, lpAmount);
        _mint(p2eManager, p2eAmount);

        emit Distributed(lpAmount, p2eAmount);
    }

    // ============================================================
    // RESCUE FITUR (Tarik Koin/Token Nyangkut)
    // ============================================================

    /**
     * @dev Wajib ada biar smart contract ini bisa nerima transfer koin native (ETH/BNB/MATIC dll).
     */
    receive() external payable {}

    /**
     * @dev Tarik saldo koin native yang masuk ke kontrak ini. Dikirim langsung ke wallet Owner.
     */
    function withdrawNative() external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "Saldo koin native kosong");

        (bool success, ) = payable(owner()).call{value: balance}("");
        require(success, "Gagal menarik koin native");

        emit EmergencyWithdrawNative(owner(), balance);
    }

    /**
     * @dev Tarik token ERC-20 lain (misal USDT) yang nyangkut di kontrak ini ke wallet Owner.
     */
    function rescueToken(address tokenAddress) external onlyOwner {
        // Biar lu gak gak sengaja narik supply token lu sendiri dari kontrak
        require(tokenAddress != address(this), "Gak bisa narik SRp dari fungsi ini");

        uint256 balance = IERC20(tokenAddress).balanceOf(address(this));
        require(balance > 0, "Saldo token tersebut kosong");

        IERC20(tokenAddress).safeTransfer(owner(), balance);

        emit EmergencyRescueToken(tokenAddress, owner(), balance);
    }
}

contracts/SurpSidy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/governance/TimelockController.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./interfaces/SurpSwapV3Interfaces.sol";

interface IERC20Custom {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address user) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface IWETH {
    function deposit() external payable;
    function withdraw(uint256) external;
    function approve(address spender, uint256 amount) external returns (bool);
}

interface ILPManager {
    function useForLP(uint256 amount) external returns (uint256);
}

contract SurpSidy is Ownable2Step, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    uint256 public constant CONFIG_TIMELOCK_DELAY = 1 days;
    uint256 private constant BUY_SLIPPAGE_BPS = 200;
    TimelockController public immutable configTimelock;
    uint256 public configOperationNonce;

    IERC20 public token;
    IERC20 public tokenB;
    IWETH public weth;
    ISurpSwapV3SwapRouter public router;
    ISurpSwapV3PositionManager public pm;
    ISurpSwapV3Quoter public quoter;
    ISurpSwapV3QuoterV2 public quoterV2;
    ILPManager public lpManager;

    mapping(uint24 => ISurpSwapV3Pool) public feePools;
    uint32 public twapInterval = 180;     
    uint24 public maxTwapDeviation = 200; 
    mapping(uint24 => ISurpSwapV3Pool) public tokenBFeePools;
    uint32 public tokenBTwapInterval = 180;
    uint24 public tokenBMaxTwapDeviation = 200;

    enum BuyMode { LP_FIRST, SWAP_FIRST, PURE_SWAP, LP50_SWAP50 }
    mapping(BuyMode => bool) public enabledBuyModes;

    bool public sellPaused;
    bool public emergencyStop;

    uint256 public maxSubsidyPerTx = 9999999999999999999999999999999999999999999999999999 ether;
    uint256 public dailySubsidyLimit = 9999999999999999999999999999999999999999999999999999 ether;
    uint256 public usedToday;
    uint256 public lastReset;
    uint256 public maxDeviationBps = 500;

    mapping(address => uint256) public lastBuy;
    uint256[] public lpPositions;

    modifier notStopped() {
        require(!emergencyStop, "stopped");
        _;
    }

    modifier validFee(uint24 fee) {
        require(fee == 3000 || fee == 10000, "Invalid fee tier. Only 0.3% or 1% allowed");
        _;
    }

    modifier onlyOwnerOrConfigTimelock() {
        require(
            msg.sender == owner() || msg.sender == address(configTimelock),
            "not owner or timelock"
        );
        _;
    }

    constructor(
        address _token,
        address _weth,
        address _router,
        address _pm,
        address _quoter,
        address _quoterV2,
        address _lp
    ) {
        token = IERC20(_token);
        weth = IWETH(_weth);
        _validateSurpSwapCore(_router, _pm, _quoter, _quoterV2);
        router = ISurpSwapV3SwapRouter(_router);
        pm = ISurpSwapV3PositionManager(_pm);
        quoter = ISurpSwapV3Quoter(_quoter);
        quoterV2 = ISurpSwapV3QuoterV2(_quoterV2);
        lpManager = ILPManager(_lp);
        address[] memory proposers = new address[](1);
        proposers[0] = address(this);
        address[] memory executors = new address[](1);
        executors[0] = address(0);
        configTimelock = new TimelockController(
            CONFIG_TIMELOCK_DELAY,
            proposers,
            executors,
            address(0)
        );
        lastReset = block.timestamp;
        enabledBuyModes[BuyMode.LP_FIRST]=true;
        enabledBuyModes[BuyMode.SWAP_FIRST]=true;
        enabledBuyModes[BuyMode.PURE_SWAP]=true;
        enabledBuyModes[BuyMode.LP50_SWAP50]=true;
    }

    function _validateSurpSwapCore(
        address routerAddress,
        address positionManagerAddress,
        address quoterAddress,
        address quoterV2Address
    ) private view {
        require(
            routerAddress.code.length > 0 &&
                positionManagerAddress.code.length > 0 &&
                quoterAddress.code.length > 0 &&
                quoterV2Address.code.length > 0,
            "Invalid SurpSwap periphery"
        );
        address factory = ISurpSwapV3SwapRouter(routerAddress).factory();
        require(factory.code.length > 0, "Invalid SurpSwap factory");
        require(
            ISurpSwapV3PositionManager(positionManagerAddress).factory() == factory &&
                ISurpSwapV3Quoter(quoterAddress).factory() == factory &&
                ISurpSwapV3QuoterV2(quoterV2Address).factory() == factory,
            "SurpSwap factory mismatch"
        );
    }

    // ============================================================
    // BUY
    // ============================================================
    function buy(BuyMode mode, uint24 fee)
        external
        payable
        nonReentrant
        notStopped
        validFee(fee)
    {
        _buy(mode, fee, 0, block.timestamp);
    }

    function buy(
        BuyMode mode,
        uint24 fee,
        uint256 amountOutMinimum,
        uint256 deadline
    )
        external
        payable
        nonReentrant
        notStopped
        validFee(fee)
    {
        require(amountOutMinimum > 0, "Minimum output nol");
        require(deadline >= block.timestamp, "Transaction expired");
        _buy(mode, fee, amountOutMinimum, deadline);
    }

    function buyWithProtection(
        BuyMode mode,
        uint24 fee,
        uint256 amountOutMinimum,
        uint256 deadline
    )
        external
        payable
        nonReentrant
        notStopped
        validFee(fee)
    {
        require(amountOutMinimum > 0, "Minimum output nol");
        require(deadline >= block.timestamp, "Transaction expired");
        _buy(mode, fee, amountOutMinimum, deadline);
    }

    function _buy(
        BuyMode mode,
        uint24 fee,
        uint256 amountOutMinimum,
        uint256 deadline
    ) internal {
        require(msg.value > 0, "no ETH");
        require(block.timestamp > lastBuy[msg.sender] + 10, "cooldown");

        _validateTWAP(fee);
        require(enabledBuyModes[mode], "Buy mode disabled");

        lastBuy[msg.sender] = block.timestamp;
        (int24 tickLower, int24 tickUpper) = _getTicks(fee);

        if (mode == BuyMode.LP_FIRST) {
            _buyLpFirst(
                msg.value,
                fee,
                tickLower,
                tickUpper,
                amountOutMinimum,
                deadline
            );
        } else if (mode == BuyMode.SWAP_FIRST) {
            _buySwapFirst(
                msg.value,
                fee,
                tickLower,
                tickUpper,
                amountOutMinimum,
                deadline
            );
        } else if (mode == BuyMode.LP50_SWAP50) {
            _buyLp50Swap50(
                msg.value,
                fee,
                tickLower,
                tickUpper,
                amountOutMinimum,
                deadline
            );
        } else {
            _buyPure(msg.value, fee, amountOutMinimum, deadline);
        }
    }

    function _buyLpFirst(
        uint256 eth,
        uint24 fee,
        int24 tickLower,
        int24 tickUpper,
        uint256 amountOutMinimum,
        uint256 deadline
    ) internal {
        uint256 lpEth = eth / 2;
        uint256 swapEth = eth - lpEth;

        uint256 totalMarketValue = _getExactMarketPrice(eth, fee); 

        uint256 tokenValueForLP = _getMinOut(lpEth, fee);
        uint256 srpLP = lpManager.useForLP(tokenValueForLP);             

        _addLiquidity(lpEth, srpLP, fee, tickLower, tickUpper, deadline); 

        uint256 out = _swapETH(swapEth, fee, deadline);

        uint256 finalTransferAmount = out;
        if (totalMarketValue > out) {
            uint256 deficit = totalMarketValue - out;

            _checkAndUpdateSubsidy(deficit);

            uint256 exactSubsidy = lpManager.useForLP(deficit);
            finalTransferAmount += exactSubsidy;
        }

        require(finalTransferAmount >= amountOutMinimum, "Insufficient token output");
        token.safeTransfer(msg.sender, finalTransferAmount);
    }

    function _buySwapFirst(
        uint256 eth,
        uint24 fee,
        int24 tickLower,
        int24 tickUpper,
        uint256 amountOutMinimum,
        uint256 deadline
    ) internal {
        uint256 swapEth = eth / 2;
        uint256 lpEth = eth - swapEth;

        uint256 totalMarketValue = _getExactMarketPrice(eth, fee);

        uint256 out = _swapETH(swapEth, fee, deadline);

        uint256 tokenValueForLP = _getMinOut(lpEth, fee);
        uint256 srpLP = lpManager.useForLP(tokenValueForLP);             
        _addLiquidity(lpEth, srpLP, fee, tickLower, tickUpper, deadline);

        uint256 finalTransferAmount = out;
        if (totalMarketValue > out) {
            uint256 deficit = totalMarketValue - out;

            _checkAndUpdateSubsidy(deficit);

            uint256 exactSubsidy = lpManager.useForLP(deficit);
            finalTransferAmount += exactSubsidy;
        }

        require(finalTransferAmount >= amountOutMinimum, "Insufficient token output");
        token.safeTransfer(msg.sender, finalTransferAmount);
    }

    function _buyLp50Swap50(
        uint256 eth,
        uint24 fee,
        int24 tickLower,
        int24 tickUpper,
        uint256 amountOutMinimum,
        uint256 deadline
    ) internal {
        uint256 lpEth = eth / 2;
        uint256 swapEth = eth - lpEth;
        uint256 tokenValueForLP = _getMinOut(lpEth, fee);
        uint256 srpLP = lpManager.useForLP(tokenValueForLP);
        _addLiquidity(lpEth, srpLP, fee, tickLower, tickUpper, deadline);
        uint256 out = _swapETH(swapEth, fee, deadline);
        require(out >= amountOutMinimum, "Insufficient token output");
        token.safeTransfer(msg.sender, out);
    }

    function _buyPure(
        uint256 eth,
        uint24 fee,
        uint256 amountOutMinimum,
        uint256 deadline
    ) internal {
        uint256 out = _swapETH(eth, fee, deadline);
        require(out >= amountOutMinimum, "Insufficient token output");
        token.safeTransfer(msg.sender, out); 
    }

    function buyWithTokenB(
        uint256 amount,
        BuyMode mode,
        uint24 fee,
        uint256 amountOutMinimum
    ) external nonReentrant notStopped validFee(fee) {
        require(address(tokenB) != address(0), "Token B belum dikonfigurasi");
        require(amount > 0, "Jumlah token B nol");
        require(block.timestamp > lastBuy[msg.sender] + 10, "cooldown");
        require(enabledBuyModes[mode], "Buy mode disabled");

        _validateTWAPForPool(
            tokenBFeePools[fee],
            tokenBTwapInterval,
            tokenBMaxTwapDeviation
        );

        lastBuy[msg.sender] = block.timestamp;
        tokenB.safeTransferFrom(msg.sender, address(this), amount);

        (int24 tickLower, int24 tickUpper) = _getTicksForPool(
            fee,
            tokenBFeePools[fee]
        );
        uint256 out;

        if (mode == BuyMode.PURE_SWAP) {
            out = _swapTokenB(amount, fee, amountOutMinimum);
        } else {
            uint256 lpAmount = amount / 2;
            uint256 swapAmount = amount - lpAmount;

            if (mode == BuyMode.LP_FIRST || mode == BuyMode.LP50_SWAP50) {
                _addTokenBLiquidity(lpAmount, fee, tickLower, tickUpper);
                out = _swapTokenB(swapAmount, fee, 0);
            } else {
                out = _swapTokenB(swapAmount, fee, 0);
                _addTokenBLiquidity(lpAmount, fee, tickLower, tickUpper);
            }

            if (mode != BuyMode.LP50_SWAP50) {
                uint256 expected = _getQuote(address(tokenB), address(token), amount, fee);
                if (expected > out) {
                    uint256 subsidy = expected - out;
                    _checkAndUpdateSubsidy(subsidy);
                    out += lpManager.useForLP(subsidy);
                }
            }
        }

        require(out >= amountOutMinimum, "Insufficient token output");
        token.safeTransfer(msg.sender, out);
    }

    // ============================================================
    // SWAP
    // ============================================================
    function _swapETH(uint256 amount, uint24 fee, uint256 deadline) internal returns (uint256) {
        uint256 quoted = _getExactMarketPrice(amount, fee);
        uint256 minOut = (quoted * (10000 - BUY_SLIPPAGE_BPS)) / 10000;

        weth.deposit{value: amount}();
        weth.approve(address(router), 0);
        weth.approve(address(router), amount);

        uint256 out = router.exactInputSingle(
            ISurpSwapV3SwapRouter.ExactInputSingleParams({
                tokenIn: address(weth),
                tokenOut: address(token),
                fee: fee,
                recipient: address(this),
                deadline: deadline,
                amountIn: amount,
                amountOutMinimum: minOut,
                sqrtPriceLimitX96: 0
            })
        );

        _validatePrice(quoted, out);
        return out;
    }

    function _swapTokenB(
        uint256 amount,
        uint24 fee,
        uint256 amountOutMinimum
    ) internal returns (uint256) {
        uint256 quoted = _getQuote(address(tokenB), address(token), amount, fee);
        uint256 minOut = (quoted * (10000 - BUY_SLIPPAGE_BPS)) / 10000;
        if (amountOutMinimum > minOut) {
            minOut = amountOutMinimum;
        }

        tokenB.safeApprove(address(router), 0);
        tokenB.safeApprove(address(router), amount);

        uint256 out = router.exactInputSingle(
            ISurpSwapV3SwapRouter.ExactInputSingleParams({
                tokenIn: address(tokenB),
                tokenOut: address(token),
                fee: fee,
                recipient: address(this),
                deadline: block.timestamp,
                amountIn: amount,
                amountOutMinimum: minOut,
                sqrtPriceLimitX96: 0
            })
        );

        _validatePrice(quoted, out);
        return out;
    }

    function _getMinOut(uint256 amount, uint24 fee) internal returns (uint256) {
        uint256 quoted = _getExactMarketPrice(amount, fee);
        return (quoted * (10000 - BUY_SLIPPAGE_BPS)) / 10000;
    }

    function _getExactMarketPrice(uint256 amount, uint24 fee) internal returns (uint256) {
        return _getQuote(address(weth), address(token), amount, fee);
    }

    function _getQuote(address tokenIn, address tokenOut, uint256 amount, uint24 fee)
        internal
        returns (uint256 quoted)
    {
        try quoter.quoteExactInputSingle(
            tokenIn,
            tokenOut,
            fee,
            amount,
            0
        ) returns (uint256 amountOut) {
            quoted = amountOut;
        } catch (bytes memory reason) {
            if (reason.length == 32) {
                quoted = abi.decode(reason, (uint256));
            } else {
                revert("SurpSwap quoter failed");
            }
        }
    }

    function _validatePrice(uint256 quoted, uint256 actual) internal view {
        require(quoted > 0, "Harga quote nol");
        uint256 diff = quoted > actual ? quoted - actual : actual - quoted;
        require((diff * 10000) / quoted < maxDeviationBps, "manipulated");
    }

    // ============================================================
    // LP
    // ============================================================
    function _addLiquidity(
        uint256 ethAmount,
        uint256 tokenAmount,
        uint24 fee,
        int24 tickLower,
        int24 tickUpper,
        uint256 deadline
    ) internal returns (uint256) {
        weth.deposit{value: ethAmount}();

        weth.approve(address(pm), 0);
        weth.approve(address(pm), ethAmount);

        token.approve(address(pm), 0);
        token.approve(address(pm), tokenAmount);

        bool isToken0 = address(token) < address(weth);
        address t0 = isToken0 ? address(token) : address(weth);
        address t1 = isToken0 ? address(weth) : address(token);
        uint256 a0 = isToken0 ? tokenAmount : ethAmount;
        uint256 a1 = isToken0 ? ethAmount : tokenAmount;

        (uint256 id,, uint256 amount0, uint256 amount1) = pm.mint(
            ISurpSwapV3PositionManager.MintParams({
                token0: t0,
                token1: t1,
                fee: fee,
                tickLower: tickLower,
                tickUpper: tickUpper,
                amount0Desired: a0,
                amount1Desired: a1,
                amount0Min: 0,
                amount1Min: 0,
                recipient: address(this), 
                deadline: deadline
            })
        );
        lpPositions.push(id);

        uint256 usedToken = isToken0 ? amount0 : amount1;
        return usedToken; 
    }

    function _getTicks(uint24 fee) internal view returns (int24, int24) {
        return _getTicksForPool(fee, feePools[fee]);
    }

    function _getTicksForPool(uint24 fee, ISurpSwapV3Pool targetPool)
        internal
        view
        returns (int24, int24)
    {
        require(address(targetPool) != address(0), "Pool belum di-set");

        (, int24 currentTick,,,,,) = targetPool.slot0();
        int24 spacing = fee == 3000 ? int24(60) : int24(200);

        int24 lower = (currentTick / spacing) * spacing - (spacing * 100);
        int24 upper = (currentTick / spacing) * spacing + (spacing * 100);
        return (lower, upper);
    }

    function _addTokenBLiquidity(
        uint256 tokenBAmount,
        uint24 fee,
        int24 tickLower,
        int24 tickUpper
    ) internal {
        uint256 tokenAmount = lpManager.useForLP(
            _getQuote(address(tokenB), address(token), tokenBAmount, fee)
        );
        _mintTokenBLiquidity(
            tokenBAmount,
            tokenAmount,
            fee,
            tickLower,
            tickUpper
        );
    }

    function _mintTokenBLiquidity(
        uint256 tokenBAmount,
        uint256 tokenAmount,
        uint24 fee,
        int24 tickLower,
        int24 tickUpper
    ) internal {
        tokenB.safeApprove(address(pm), 0);
        tokenB.safeApprove(address(pm), tokenBAmount);
        token.safeApprove(address(pm), 0);
        token.safeApprove(address(pm), tokenAmount);

        bool isToken0 = address(token) < address(tokenB);
        (uint256 id,,,) = pm.mint(
            ISurpSwapV3PositionManager.MintParams({
                token0: isToken0 ? address(token) : address(tokenB),
                token1: isToken0 ? address(tokenB) : address(token),
                fee: fee,
                tickLower: tickLower,
                tickUpper: tickUpper,
                amount0Desired: isToken0 ? tokenAmount : tokenBAmount,
                amount1Desired: isToken0 ? tokenBAmount : tokenAmount,
                amount0Min: 0,
                amount1Min: 0,
                recipient: address(this),
                deadline: block.timestamp
            })
        );
        lpPositions.push(id);
    }

    // ============================================================
    // AUTO COMPOUND 
    // ============================================================
    function autoCompound(uint256 tokenId, uint24 fee) external onlyOwner validFee(fee) {
        (uint256 amount0, uint256 amount1) = pm.collect(
            ISurpSwapV3PositionManager.CollectParams({
                tokenId: tokenId,
                recipient: address(this),
                amount0Max: type(uint128).max,
                amount1Max: type(uint128).max
            })
        );

        bool isToken0 = address(token) < address(weth);
        uint256 tokenAmt = isToken0 ? amount0 : amount1;
        uint256 wethAmt = isToken0 ? amount1 : amount0;

        token.approve(address(pm), 0);
        token.approve(address(pm), tokenAmt);

        weth.approve(address(pm), 0);
        weth.approve(address(pm), wethAmt);

        (int24 tickLower, int24 tickUpper) = _getTicks(fee);

        address t0 = isToken0 ? address(token) : address(weth);
        address t1 = isToken0 ? address(weth) : address(token);
        uint256 a0 = isToken0 ? tokenAmt : wethAmt;
        uint256 a1 = isToken0 ? wethAmt : tokenAmt;

        pm.mint(
            ISurpSwapV3PositionManager.MintParams({
                token0: t0,
                token1: t1,
                fee: fee,
                tickLower: tickLower,
                tickUpper: tickUpper,
                amount0Desired: a0,
                amount1Desired: a1,
                amount0Min: 0,
                amount1Min: 0,
                recipient: address(this),
                deadline: block.timestamp
            })
        );
    }

    function autoCompoundTokenB(uint256 tokenId, uint24 fee)
        external
        onlyOwner
        validFee(fee)
    {
        require(address(tokenB) != address(0), "Token B belum dikonfigurasi");
        (int24 tickLower, int24 tickUpper) = _getTicksForPool(
            fee,
            tokenBFeePools[fee]
        );
        (uint256 amount0, uint256 amount1) = pm.collect(
            ISurpSwapV3PositionManager.CollectParams({
                tokenId: tokenId,
                recipient: address(this),
                amount0Max: type(uint128).max,
                amount1Max: type(uint128).max
            })
        );

        bool isToken0 = address(token) < address(tokenB);
        _mintTokenBLiquidity(
            isToken0 ? amount1 : amount0,
            isToken0 ? amount0 : amount1,
            fee,
            tickLower,
            tickUpper
        );
    }

